from pathlib import Path
import base64
import io
import shutil
import tarfile

APP = Path("android/OrbisG28Bridge")
PC_DIR = Path("pc/orbis_g28_bridge")
PAYLOAD = ''

old_java = APP / "app/src/main/java"
if old_java.exists(): shutil.rmtree(old_java)
old_aidl = APP / "app/src/main/aidl"
if old_aidl.exists(): shutil.rmtree(old_aidl)

with tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD)), mode="r:gz") as archive:
    archive.extractall("/tmp/orbis_bridge_payload")

java_dir = APP / "app/src/main/java/com/orbisg28bridge"
java_dir.mkdir(parents=True, exist_ok=True)
shutil.copy2("/tmp/orbis_bridge_payload/BridgeActivity.java", java_dir / "BridgeActivity.java")
PC_DIR.mkdir(parents=True, exist_ok=True)
for name in ("orbis_g28_pc.py", "INSTRUCOES.txt", "requirements.txt"):
    shutil.copy2(Path("/tmp/orbis_bridge_payload/pc") / name, PC_DIR / name)

manifest = """<manifest xmlns:android="http://schemas.android.com/apk/res/android">
    <uses-feature android:name="android.hardware.bluetooth_le" android:required="true" />
    <uses-permission android:name="android.permission.INTERNET" />
    <uses-permission android:name="android.permission.BLUETOOTH" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.BLUETOOTH_ADMIN" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" android:maxSdkVersion="30" />
    <uses-permission android:name="android.permission.BLUETOOTH_SCAN" android:usesPermissionFlags="neverForLocation" />
    <uses-permission android:name="android.permission.BLUETOOTH_CONNECT" />
    <application android:allowBackup="false" android:icon="@mipmap/ic_launcher"
        android:roundIcon="@mipmap/ic_launcher" android:label="Orbis G28 BLE Bridge"
        android:supportsRtl="true" android:theme="@style/AppTheme">
        <activity android:name=".BridgeActivity" android:exported="true" android:screenOrientation="portrait">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>
    </application>
</manifest>
"""
(APP / "app/src/main/AndroidManifest.xml").write_text(manifest, encoding="utf-8")

build_gradle = """plugins { id 'com.android.application' }
android {
    namespace 'com.orbisg28bridge'
    compileSdk 35
    defaultConfig {
        applicationId 'com.orbisg28bridge'
        minSdk 24
        targetSdk 35
        versionCode 200
        versionName '2.0-adb-ble-bridge'
    }
    compileOptions {
        coreLibraryDesugaringEnabled true
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }
}
dependencies {
    coreLibraryDesugaring 'com.android.tools:desugar_jdk_libs:2.1.5'
}
"""
(APP / "app/build.gradle").write_text(build_gradle, encoding="utf-8")

Path("android/OrbisG28Bridge/README_BRIDGE.md").write_text(
    "# Orbis G28 Android BLE Bridge v2.0\n\n"
    "PC -> ADB forward TCP 8765 -> Android -> BLE -> G28 OTA.\n\n"
    "Somente D5/0F e D5/01 são aceitos. As classes antigas de laboratório são removidas antes do build.\n",
    encoding="utf-8",
)
